    void childrenTakeRoomSpaceButDoNotPay() {
        Guest guest = new Guest("Ana Souza", "ana\@example.com", "123.456.789-09");
        LocalDate in = LocalDate.parse("2027-03-10");
        LocalDate out = LocalDate.parse("2027-03-13");

        Reservation reservation = service.create(new NewReservation(101, guest, in, out, 1, 1, RatePlan.STANDARD));

        assertEquals(1, reservation.children());
        assertEquals(new BigDecimal("749.70"), reservation.price().total());
        assertEquals(0, stay(101, "2027-03-10", "2027-03-13", 1, RatePlan.STANDARD).children());
        assertEquals(ErrorCode.CAPACITY_EXCEEDED, errorOf(() -> service.create(
                new NewReservation(201, guest, in, out, 2, 1, RatePlan.STANDARD))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(
                new NewReservation(201, guest, in, out, 1, -1, RatePlan.STANDARD))));
    }

    \@Test
    void theReceiptShowsChildrenOnlyWhenThereAreSome() {
        Guest guest = new Guest("Ana Souza", "ana\@example.com", "123.456.789-09");
        LocalDate in = LocalDate.parse("2027-03-10");
        LocalDate out = LocalDate.parse("2027-03-11");
        Reservation withChildren = service.create(new NewReservation(101, guest, in, out, 1, 1, RatePlan.STANDARD));
        Reservation without = service.create(stay(102, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
        service.confirm(withChildren.id());
        service.confirm(without.id());

        String text = service.receiptCopy(withChildren.id()).text();
        assertTrue(text.contains("Quarto: 101 (STANDARD)\nCrianças: 1\nEntrada"));
        assertFalse(service.receiptCopy(without.id()).text().contains("Crianças"));
    }

